#include "streaming/streaming.hpp"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <limits>
#include <stdexcept>
namespace kg::stream {
uint64_t mix64(uint64_t x) { x+=0x9e3779b97f4a7c15ULL; x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL; x=(x^(x>>27))*0x94d049bb133111ebULL; return x^(x>>31); }
ChunkKey keyAt(double x,double z,double s) { if(!(s>0) || !std::isfinite(s) || !std::isfinite(x) || !std::isfinite(z)) throw std::invalid_argument("invalid coordinates/size"); const double a=std::floor(x/s),b=std::floor(z/s); if(a<std::numeric_limits<int>::min()||a>std::numeric_limits<int>::max()||b<std::numeric_limits<int>::min()||b>std::numeric_limits<int>::max()) throw std::out_of_range("chunk coordinates"); return {int(a),int(b)}; }
static double smooth(double t){return t*t*(3-2*t);}
static double rand2(int64_t x,int64_t z,uint64_t seed){return double(mix64(seed^mix64(uint64_t(x))^mix64(uint64_t(z)+0xabc123))>>11)*(1.0/9007199254740992.0);}
static double noise2(double x,double z,uint64_t seed){auto ix=int64_t(std::floor(x)),iz=int64_t(std::floor(z));double u=smooth(x-double(ix)),v=smooth(z-double(iz));double a=rand2(ix,iz,seed),b=rand2(ix+1,iz,seed),c=rand2(ix,iz+1,seed),d=rand2(ix+1,iz+1,seed);return std::lerp(std::lerp(a,b,u),std::lerp(c,d,u),v);}
double heightAt(double x,double z,uint64_t seed){double h=0,amp=18,frequency=1.0/180;for(int i=0;i<5;++i){h+=(noise2(x*frequency,z*frequency,seed+uint64_t(i)*17)-.5)*2*amp; amp*=.5;frequency*=2;}return h;}
double caveField(double x,double y,double z,uint64_t seed){const double a=noise2(x*.043+y*.019,z*.043,seed^0x321ULL);const double b=noise2(x*.07,z*.07+y*.024,seed^0x987ULL);return .6*a+.4*b;}
bool caveSolid(double x,double y,double z,uint64_t seed,double threshold){return caveField(x,y,z,seed)<=threshold;}
bool validConfig(const Config& c,std::string* why){std::string err; if(!(c.chunkSize>0) || !std::isfinite(c.chunkSize))err="chunkSize must be positive and finite";else if(c.resolution<3||c.resolution>513)err="resolution outside [3,513]";else if(c.activeRadius<0||c.activeRadius>32)err="activeRadius outside [0,32]";else if(c.cacheLimit<(2*c.activeRadius+1)*(2*c.activeRadius+1))err="cacheLimit smaller than active set";else if(!(c.caveThreshold>=0&&c.caveThreshold<=1))err="caveThreshold outside [0,1]";if(why)*why=err;return err.empty();}
Mesh buildTerrainChunk(ChunkKey key,const Config& c,int lod){if(!validConfig(c)||lod<0||lod>8)throw std::invalid_argument("bad chunk configuration/lod");int segments=std::max(2,(c.resolution-1)>>lod);Mesh m; m.name="terrain_"+std::to_string(key.x)+"_"+std::to_string(key.z);m.vertices.reserve(size_t(segments+1)*(segments+1));m.indices.reserve(size_t(segments)*segments*6);for(int z=0;z<=segments;++z)for(int x=0;x<=segments;++x){double px=(double(key.x)+double(x)/segments)*c.chunkSize,pz=(double(key.z)+double(z)/segments)*c.chunkSize;double h=heightAt(px,pz,c.seed);double eps=0.5;double dx=heightAt(px+eps,pz,c.seed)-heightAt(px-eps,pz,c.seed),dz=heightAt(px,pz+eps,c.seed)-heightAt(px,pz-eps,c.seed);double inv=1/std::sqrt(dx*dx+dz*dz+4*eps*eps);Vertex v;v.p={px,h,pz};v.n={-dx*inv,2*eps*inv,-dz*inv};v.u=float(double(x)/segments);v.v=float(double(z)/segments);m.vertices.push_back(v);}for(int z=0;z<segments;++z)for(int x=0;x<segments;++x){auto a=uint32_t(z*(segments+1)+x),b=a+1,d=a+uint32_t(segments+1),e=d+1;m.indices.insert(m.indices.end(),{a,d,b,b,d,e});}return m;}
std::vector<uint8_t> buildCaveMask(ChunkKey key,const Config& c,int lod){if(!validConfig(c)||lod<0||lod>8)throw std::invalid_argument("bad config/lod");int segments=std::max(2,(c.resolution-1)>>lod);std::vector<uint8_t> mask;mask.reserve(size_t(segments+1)*(segments+1));for(int z=0;z<=segments;++z)for(int x=0;x<=segments;++x){double px=(double(key.x)+double(x)/segments)*c.chunkSize,pz=(double(key.z)+double(z)/segments)*c.chunkSize;double y=heightAt(px,pz,c.seed)-8;mask.push_back(uint8_t(!caveSolid(px,y,pz,c.seed,c.caveThreshold)));}return mask;}
uint64_t fingerprint(const Chunk& c){uint64_t h=mix64(uint64_t(uint32_t(c.key.x))^(uint64_t(uint32_t(c.key.z))<<32));for(const auto& v:c.mesh.vertices){for(double f:{v.p.x,v.p.y,v.p.z}){int64_t q=int64_t(std::llround(f*1000));h=mix64(h^uint64_t(q));}}for(auto b:c.caveMask)h=mix64(h^b);return h;}
int lodForDistance(double d,double size,int maxLod){if(!std::isfinite(d)||d<0||!std::isfinite(size)||size<=0||maxLod<0)throw std::invalid_argument("bad LOD arguments");int lod=0;while(lod<maxLod&&d>=size*(2<<lod))++lod;return lod;}
std::vector<ChunkKey> desiredChunks(double x,double z,const Config& c){if(!validConfig(c))throw std::invalid_argument("invalid config");auto center=keyAt(x,z,c.chunkSize);std::vector<ChunkKey> keys;for(int dz=-c.activeRadius;dz<=c.activeRadius;++dz)for(int dx=-c.activeRadius;dx<=c.activeRadius;++dx)keys.push_back({center.x+dx,center.z+dz});return keys;}
bool intersectsViewRadius(ChunkKey k,double x,double z,double radius,double size){if(radius<0||!std::isfinite(radius)||size<=0)throw std::invalid_argument("bad radius/size");double minx=k.x*size,maxx=minx+size,minz=k.z*size,maxz=minz+size;double dx=x-std::clamp(x,minx,maxx),dz=z-std::clamp(z,minz,maxz);return dx*dx+dz*dz<=radius*radius;}
Mesh buildBridge(const Vec3& a,const Vec3& b,double width,double deckHeight){if(!(width>0)||!std::isfinite(width)||!std::isfinite(deckHeight))throw std::invalid_argument("invalid bridge");double dx=b.x-a.x,dz=b.z-a.z,len=std::hypot(dx,dz);if(len<1e-6)throw std::invalid_argument("bridge length zero");double nx=-dz/len*width*.5,nz=dx/len*width*.5;Mesh m;m.name="bridge";Vec3 pts[8]={{a.x+nx,deckHeight,a.z+nz},{a.x-nx,deckHeight,a.z-nz},{b.x+nx,deckHeight,b.z+nz},{b.x-nx,deckHeight,b.z-nz},{a.x+nx,deckHeight-.6,a.z+nz},{a.x-nx,deckHeight-.6,a.z-nz},{b.x+nx,deckHeight-.6,b.z+nz},{b.x-nx,deckHeight-.6,b.z-nz}};for(auto p:pts){Vertex v;v.p=p;v.n={0,1,0};m.vertices.push_back(v);}m.indices={0,1,2,2,1,3,4,6,5,6,7,5,0,2,4,2,6,4,1,5,3,3,5,7,0,4,1,1,4,5,2,3,6,3,7,6};return m;}
ChunkStreamer::ChunkStreamer(Config c):cfg_(c){std::string why;if(!validConfig(c,&why))throw std::invalid_argument(why);}
void ChunkStreamer::update(double x,double z){auto desired=desiredChunks(x,z,cfg_);++tick_;active_.clear();for(auto k:desired){active_.insert(k);auto it=chunks_.find(k);if(it!=chunks_.end()){++hits_;lastUsed_[k]=tick_;continue;}double cx=(k.x+.5)*cfg_.chunkSize,cz=(k.z+.5)*cfg_.chunkSize;int lod=lodForDistance(std::hypot(cx-x,cz-z),cfg_.chunkSize);Chunk c;c.key=k;c.size=cfg_.chunkSize;c.resolution=std::max(2,(cfg_.resolution-1)>>lod)+1;c.mesh=buildTerrainChunk(k,cfg_,lod);c.caveMask=buildCaveMask(k,cfg_,lod);c.fingerprint=fingerprint(c);chunks_.emplace(k,std::move(c));lastUsed_[k]=tick_;++generated_;}while(int(chunks_.size())>cfg_.cacheLimit){auto victim=chunks_.end();uint64_t oldest=UINT64_MAX;for(auto it=chunks_.begin();it!=chunks_.end();++it){if(active_.contains(it->first))continue;auto t=lastUsed_.at(it->first);if(t<oldest){oldest=t;victim=it;}}if(victim==chunks_.end())break;lastUsed_.erase(victim->first);chunks_.erase(victim);++evictions_;}}
const Chunk* ChunkStreamer::find(ChunkKey k)const{auto it=chunks_.find(k);return it==chunks_.end()?nullptr:&it->second;}
Stats ChunkStreamer::stats()const{return {generated_,hits_,evictions_,chunks_.size(),active_.size()};}
void exportChunkManifest(const ChunkStreamer& s,const std::filesystem::path& p){if(!p.parent_path().empty())std::filesystem::create_directories(p.parent_path());std::ofstream out(p);if(!out)throw std::runtime_error("cannot open manifest");auto st=s.stats();out<<"{\n  \"generated\": "<<st.generated<<", \"cache_hits\": "<<st.cacheHits<<", \"evictions\": "<<st.evictions<<",\n  \"chunks\": [\n";bool first=true;for(auto& [k,c]:s.chunks()){if(!first)out<<",\n";first=false;out<<"    {\"x\": "<<k.x<<", \"z\": "<<k.z<<", \"resolution\": "<<c.resolution<<", \"vertices\": "<<c.mesh.vertices.size()<<", \"triangles\": "<<c.mesh.indices.size()/3<<", \"fingerprint\": \""<<c.fingerprint<<"\"}";}out<<"\n  ]\n}\n";if(!out)throw std::runtime_error("manifest write failed");}
}
